import { Redis } from '@upstash/redis';

const redis = new Redis({
  url: process.env.UPSTASH_REDIS_REST_URL!,
  token: process.env.UPSTASH_REDIS_REST_TOKEN!,
});

async function getCachedUser(userId: string): Promise<User | null> {
  const cacheKey = `user:${userId}`;

  // Try cache first
  const cached = await redis.get<User>(cacheKey);
  if (cached) return cached;

  // Cache miss — fetch from database
  const user = await db.users.findUnique({ where: { id: userId } });
  if (!user) return null;

  // Cache for 5 minutes
  await redis.setex(cacheKey, 300, user);
  return user;
}

import { Ratelimit } from '@upstash/ratelimit';
import { Redis } from '@upstash/redis';

const ratelimit = new Ratelimit({
  redis: Redis.fromEnv(),
  limiter: Ratelimit.slidingWindow(10, '10 s'), // 10 requests per 10 seconds
  analytics: true,
});

// In your API route / middleware
export async function middleware(request: Request) {
  const ip = request.headers.get('x-forwarded-for') ?? 'anonymous';
  const { success, remaining, reset } = await ratelimit.limit(ip);

  if (!success) {
    return new Response('Too Many Requests', {
      status: 429,
      headers: { 'Retry-After': String(Math.round((reset - Date.now()) / 1000)) },
    });
  }

  return NextResponse.next();
}
